insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000049401', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000236', 'multiple_choice', 'medium', 'published', 'Determine o resultado de a distância do ponto $P=(1,0,0)$ ao plano $x=0$. Antes de concluir, faça uma leitura geométrica antes de efetuar as contas.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
