insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000494011', '40000000-0000-4000-8000-000000049401', 'Comece identificando qual relação vetorial ou geométrica está sendo pedida; essa escolha vem antes da substituição numérica.', 1), ('60000000-0000-4000-8000-000000494012', '40000000-0000-4000-8000-000000049401', 'O plano x igual a zero é o plano yz.', 2), ('60000000-0000-4000-8000-000000494013', '40000000-0000-4000-8000-000000049401', 'A distância perpendicular é o valor absoluto da coordenada x.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049401', '$d=1$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000494011', '40000000-0000-4000-8000-000000049401', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000494012', '40000000-0000-4000-8000-000000049401', 'Identifique a normal', '$n=(1,0,0).$', 2), ('70000000-0000-4000-8000-000000494013', '40000000-0000-4000-8000-000000049401', 'Meça o afastamento', 'A projeção perpendicular zera apenas a coordenada x.', 3), ('70000000-0000-4000-8000-000000494014', '40000000-0000-4000-8000-000000049401', 'Calcule', '$d=|1|=1.$', 4), ('70000000-0000-4000-8000-000000494015', '40000000-0000-4000-8000-000000049401', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000049402', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000236', 'multiple_choice', 'easy', 'published', 'Assinale a distância do ponto $P=(1,1,3)$ ao plano $z=0$? Antes de concluir, escolha a relação matemática que descreve a situação.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
