insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000494021', '40000000-0000-4000-8000-000000049402', 'Comece identificando qual relação vetorial ou geométrica está sendo pedida; essa escolha vem antes da substituição numérica.', 1), ('60000000-0000-4000-8000-000000494022', '40000000-0000-4000-8000-000000049402', 'O plano z igual a zero é o plano xy.', 2), ('60000000-0000-4000-8000-000000494023', '40000000-0000-4000-8000-000000049402', 'A distância perpendicular é o valor absoluto da coordenada z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049402', '$d=3$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000494021', '40000000-0000-4000-8000-000000049402', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000494022', '40000000-0000-4000-8000-000000049402', 'Localize o plano', 'No plano xy, toda coordenada z vale zero.', 2), ('70000000-0000-4000-8000-000000494023', '40000000-0000-4000-8000-000000049402', 'Compare a altura', '$z_P=3.$', 3), ('70000000-0000-4000-8000-000000494024', '40000000-0000-4000-8000-000000049402', 'Aplique valor absoluto', '$d=|3|=3.$', 4), ('70000000-0000-4000-8000-000000494025', '40000000-0000-4000-8000-000000049402', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
