insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049426', 'Uma esfera.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000494261', '40000000-0000-4000-8000-000000049426', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000494262', '40000000-0000-4000-8000-000000049426', 'Reconheça o padrão', 'Há três quadrados de diferenças de coordenadas.', 2), ('70000000-0000-4000-8000-000000494263', '40000000-0000-4000-8000-000000049426', 'Compare com a forma padrão', '$(x-a)^2+(y-b)^2+(z-c)^2=r^2.$', 3), ('70000000-0000-4000-8000-000000494264', '40000000-0000-4000-8000-000000049426', 'Conclua', 'Essa é exatamente a equação de uma esfera.', 4), ('70000000-0000-4000-8000-000000494265', '40000000-0000-4000-8000-000000049426', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
