insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049438', 'Um elipsoide.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000494381', '40000000-0000-4000-8000-000000049438', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000494382', '40000000-0000-4000-8000-000000049438', 'Observe os sinais', 'Os três termos quadráticos são positivos.', 2), ('70000000-0000-4000-8000-000000494383', '40000000-0000-4000-8000-000000049438', 'Observe as variáveis', 'x, y e z aparecem; portanto, a superfície não se prolonga como um cilindro.', 3), ('70000000-0000-4000-8000-000000494384', '40000000-0000-4000-8000-000000049438', 'Classifique', 'A soma de três quadrados normalizados igual a 1 define um elipsoide.', 4), ('70000000-0000-4000-8000-000000494385', '40000000-0000-4000-8000-000000049438', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
