insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000494481', '40000000-0000-4000-8000-000000049448', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000494482', '40000000-0000-4000-8000-000000049448', 'Observe os sinais', 'Os três termos quadráticos são positivos.', 2), ('70000000-0000-4000-8000-000000494483', '40000000-0000-4000-8000-000000049448', 'Observe as variáveis', 'x, y e z aparecem; portanto, a superfície não se prolonga como um cilindro.', 3), ('70000000-0000-4000-8000-000000494484', '40000000-0000-4000-8000-000000049448', 'Classifique', 'A soma de três quadrados normalizados igual a 1 define um elipsoide.', 4), ('70000000-0000-4000-8000-000000494485', '40000000-0000-4000-8000-000000049448', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000049449', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000236', 'multiple_choice', 'easy', 'published', 'Assinale o eixo do cilindro dado por $x^2+y^2=121$? Antes de concluir, justifique o resultado usando as coordenadas correspondentes.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
